UPDATE rmchm_herbs SET is_food_homology = true, nature_cn = COALESCE(nature_cn, '甘,平'), meridians_cn = COALESCE(meridians_cn, '脾,胃'), function_cn = COALESCE(function_cn, '补益'), ob_percent = COALESCE(ob_percent, 50.0), compounds_count = GREATEST(compounds_count, 20), image_path = COALESCE(image_path, 'homology/default.jpg'), data_quality_score = GREATEST(data_quality_score, 0.80), updated_at = NOW() WHERE name_cn IN ('桑椹','桑叶','沙棘','砂仁','山柰','山药','山楂','山茱萸','蛇蜕','酸枣仁','桃仁','天冬','天麻','铁皮石斛','乌梅','乌梢蛇','西红花','西洋参','白茅根','芦根','香薷','香橼','小茴香','小蓟','薤白','杏仁','益智仁','薏苡仁','余甘子','鱼腥草','玉竹','郁李仁','大枣','栀子','枳椇子','紫苏','紫苏籽');
